-- GlobalEdu MySQL schema and initial catalog data. Import this file through phpMyAdmin.
CREATE DATABASE IF NOT EXISTS globaledu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE globaledu;

CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED NOT NULL AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY users_email_unique (email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS user_settings (user_id INT UNSIGNED NOT NULL, theme ENUM('light','dark') NOT NULL DEFAULT 'light', notifications JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (user_id), CONSTRAINT user_settings_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sessions (session_id VARCHAR(128) NOT NULL, expires BIGINT UNSIGNED NOT NULL, data MEDIUMTEXT NOT NULL, PRIMARY KEY (session_id), KEY sessions_expires_idx (expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS user_workspace (owner_key VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id INT UNSIGNED NULL, data_key VARCHAR(64) NOT NULL, data_value JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (owner_key,data_key), KEY workspace_user_idx (user_id), CONSTRAINT workspace_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_records (id INT UNSIGNED NOT NULL AUTO_INCREMENT, user_id INT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, record_type VARCHAR(80) NOT NULL DEFAULT 'Custom', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY admin_records_user_idx (user_id), CONSTRAINT admin_records_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS newsletter_subscribers (id INT UNSIGNED NOT NULL AUTO_INCREMENT, email VARCHAR(254) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY newsletter_email_unique (email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS countries (id VARCHAR(32) NOT NULL, name VARCHAR(120) NOT NULL, attributes JSON NOT NULL, display_order INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS universities (id VARCHAR(32) NOT NULL, country_id VARCHAR(32) NOT NULL, name VARCHAR(200) NOT NULL, attributes JSON NOT NULL, display_order INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY universities_country_idx(country_id), CONSTRAINT universities_country_fk FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS programs (id VARCHAR(64) NOT NULL, university_id VARCHAR(32) NOT NULL, name VARCHAR(200) NOT NULL, attributes JSON NOT NULL, display_order INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY programs_university_idx(university_id), CONSTRAINT programs_university_fk FOREIGN KEY(university_id) REFERENCES universities(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS scholarships (id VARCHAR(32) NOT NULL, country_id VARCHAR(32) NOT NULL, name VARCHAR(200) NOT NULL, attributes JSON NOT NULL, display_order INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY scholarships_country_idx(country_id), CONSTRAINT scholarships_country_fk FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS departments (id VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, attributes JSON NOT NULL, display_order INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS platform_notifications (id INT UNSIGNED NOT NULL AUTO_INCREMENT, title VARCHAR(160) NOT NULL, message VARCHAR(500) NOT NULL, label VARCHAR(40) NOT NULL, tone VARCHAR(20) NOT NULL DEFAULT '', category VARCHAR(32) NOT NULL, PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS application_deadlines (id VARCHAR(64) NOT NULL, title VARCHAR(200) NOT NULL, type VARCHAR(32) NOT NULL, due_date DATE NOT NULL, university VARCHAR(200) NOT NULL, PRIMARY KEY(id), KEY deadlines_due_date_idx(due_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS document_requirements (id INT UNSIGNED NOT NULL AUTO_INCREMENT, name VARCHAR(160) NOT NULL, PRIMARY KEY(id), UNIQUE KEY document_name_unique(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;








